                if not(0<=rr<H and 0<=cc<W) or not(gi[rr][cc]==0): ok=False;break
            if ok:
                for pr,pc in pat:
                    if gi[dr0+pr][dc0+pc]==0: o[dr0+pr][dc0+pc]=col; placed.add((dr0,dc0))
    return o,pat,h,w,len(placed)
for k in ['Demo pair 2','Demo pair 3','Demo pair 4']:
    p,pat,h,w,n=solve(G[k+' input']); e=G[k+' output']
    d=[(r,c,p[r][c],e[r][c]) for r in range(len(p)) for c in range(len(p[0])) if p[r][c]!=e[r][c]]
    print(k,'pat',h,w,'placements',n,'ndiff',len(d),d[:6])
